import { EntityTfError } from "../../engine/entity.js";
import { expr, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { fieldRefToTfValue } from "../field/to-tf.js";
import { CLOUD_LINK_ORG_BAG } from "../org/cloud-link.js";
import { CONNECTOR_ORG_BAG } from "../org/connector.js";
import { SEARCH_TABLE_RESOURCE_TYPES } from "./types.js";
function fieldValue(token, ctx, where) {
    if (token?.refName === undefined || token.refName === "")
        throw new EntityTfError(`${where}: missing field token`);
    if (token.parent !== undefined && token.parent !== ctx.appRefName) {
        throw new EntityTfError(`${where}: cross-aspect field token ${token.parent}.${token.refName} is not supported`);
    }
    const value = fieldRefToTfValue(token.fieldType ?? "", token.refName, ctx.appTfLabel, ctx.parentScope);
    if (value === undefined)
        throw new EntityTfError(`${where}: field ${token.refName} has no Terraform resource mapping`);
    return value;
}
function connectorValue(token, ctx, where) {
    const key = token?.parent !== undefined ? `${token.parent}.${token.refName ?? ""}` : token?.refName ?? "";
    const resolved = ctx.orgRefs.byTsLabel(CONNECTOR_ORG_BAG, key);
    if (resolved === undefined) {
        throw new EntityTfError(`${where}: AI service token "${key}" is not in the org catalog — re-run \`elementum pull org --data-only\``);
    }
    return expr.dataAttr("elementum_ai_provider_connector", resolved.tfLabel, ["id"]);
}
export function searchTableToTf(entity, ctx) {
    if (entity.kind !== "searchTable")
        throw new EntityTfError(`searchTableToTf expects kind "searchTable"; got ${entity.kind}`);
    const payload = entity.payload;
    if (payload === null || payload.__variant === undefined)
        throw new EntityTfError(`search table ${entity.refName} has no variant payload`);
    const label = ctx.parentScope === "table" ? `tables_${ctx.appTfLabel}_${tsLabelToTfLabel(entity.refName)}` : scopedResourceLabel(ctx.appTfLabel, tsLabelToTfLabel(entity.refName), ctx.parentScope);
    if (payload.__variant === "table") {
        const columnValue = (token, where) => {
            if (!token?.refName || (token.parent !== undefined && token.parent !== ctx.appRefName))
                throw new EntityTfError(`${where}: table column must belong to ${ctx.appRefName}`);
            return expr.resourceAttr("elementum_table", ctx.appTfLabel, ["field_ids", { index: token.name ?? token.refName }]);
        };
        const attrs = {
            table_id: expr.resourceAttr("elementum_table", ctx.appTfLabel, ["id"]),
            field_id: columnValue(payload.fieldId, `search table ${entity.refName}`),
            ai_provider_connector_id: connectorValue(payload.aiProviderConnectorId, ctx, `search table ${entity.refName}`),
            attribute_field_ids: (payload.attributeFieldIds ?? []).map((field) => columnValue(field, `search table ${entity.refName}`)),
            duration: payload.duration ?? "DAYS", target_lag: payload.targetLag ?? 1,
        };
        if (payload.name !== undefined)
            attrs.name = payload.name;
        if (payload.warehouse !== undefined)
            attrs.warehouse = payload.warehouse;
        if (payload.creationTimeout !== undefined)
            attrs.creation_timeout = payload.creationTimeout;
        const block = { kind: "resource", type: SEARCH_TABLE_RESOURCE_TYPES.table, label, attrs };
        return { blocks: [block], address: `${block.type}.${label}` };
    }
    if (ctx.parentScope === "table") {
        throw new EntityTfError(`search table ${entity.refName}: ${payload.__variant} search tables cannot belong to a table`);
    }
    const aspectCtx = ctx;
    const objectId = expr.resourceAttr(ctx.parentScope === "element" ? "elementum_element" : "elementum_app", ctx.appTfLabel, ["id"]);
    if (payload.__variant === "linked") {
        const cloudLinkKey = payload.cloudLinkId?.refName ?? "";
        const cloudLink = ctx.orgRefs.byTsLabel(CLOUD_LINK_ORG_BAG, cloudLinkKey);
        if (cloudLink === undefined)
            throw new EntityTfError(`search table ${entity.refName}: cloud link ${cloudLinkKey} is not in the org catalog`);
        const attrs = {
            object_id: objectId,
            cloud_link_id: expr.dataAttr("elementum_cloudlink", cloudLink.tfLabel, ["id"]),
            database: payload.database ?? "",
            schema_name: payload.schema ?? "",
            service_name: payload.serviceName ?? "",
        };
        if (payload.warehouse !== undefined)
            attrs["warehouse"] = payload.warehouse;
        const block = { kind: "resource", type: SEARCH_TABLE_RESOURCE_TYPES.linked, label, attrs };
        return { blocks: [block], address: `${block.type}.${label}` };
    }
    const index = payload.vectorIndexes?.[0] ??
        (payload.fieldId !== undefined || payload.aiProviderConnectorId !== undefined
            ? { fieldId: payload.fieldId, aiProviderConnectorId: payload.aiProviderConnectorId }
            : undefined);
    if (index === undefined)
        throw new EntityTfError(`search table ${entity.refName}: no vector index`);
    if ((payload.vectorIndexes?.length ?? 0) > 1)
        throw new EntityTfError(`search table ${entity.refName}: Terraform supports exactly one vector index`);
    const attrs = {
        object_id: objectId,
        field_id: fieldValue(index.fieldId, aspectCtx, `search table ${entity.refName}`),
        ai_provider_connector_id: connectorValue(index.aiProviderConnectorId, ctx, `search table ${entity.refName}`),
        attribute_field_ids: (payload.attributeFieldIds ?? []).map((field) => fieldValue(field, aspectCtx, `search table ${entity.refName}`)),
        duration: payload.duration ?? "DAYS",
        target_lag: payload.targetLag ?? 1,
    };
    if (payload.textIndexFieldIds !== undefined) {
        attrs["text_index_field_ids"] = payload.textIndexFieldIds.map((field) => fieldValue(field, aspectCtx, `search table ${entity.refName}`));
    }
    if (payload.name !== undefined)
        attrs["name"] = payload.name;
    if (payload.warehouse !== undefined)
        attrs["warehouse"] = payload.warehouse;
    if (payload.creationTimeout !== undefined)
        attrs["creation_timeout"] = payload.creationTimeout;
    const block = { kind: "resource", type: SEARCH_TABLE_RESOURCE_TYPES.snowflake, label, attrs };
    return { blocks: [block], address: `${block.type}.${label}` };
}
